// ============================================================
// HELPERS
// ============================================================

/** Convert internal route → URL path */
export function routeToPath(route: string): string {
  const match = PUBLIC_ROUTES.find(r => r.route === route);
  return match?.path ?? "/";
}

/** Convert URL path → internal route */
export function pathToRoute(path: string): string {
  // Normalize: remove trailing slash, ensure leading slash
  const normalized = path === "/" ? "/" : path.replace(/\/$/, "");
  const match = PUBLIC_ROUTES.find(r => r.path === normalized);
  return match?.route ?? "home";
}

/** Get route definition by internal route key */
export function getRouteDef(route: string): RouteDef | undefined {
  return PUBLIC_ROUTES.find(r => r.route === route);
}

/** Get route definition by URL path */
export function getRouteDefByPath(path: string): RouteDef | undefined {
  const normalized = path === "/" ? "/" : path.replace(/\/$/, "");
  return PUBLIC_ROUTES.find(r => r.path === normalized);
}

/** All routes for sitemap (excluding non-indexable ones) */
export function getSitemapRoutes(): RouteDef[] {
  return PUBLIC_ROUTES.filter(r => r.sitemap !== false);
}
